package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A period of a sheet: a name unique on the sheet, from and to dates inclusive. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    /** Whether the period is closed: no claim dated inside it can then be added, edited or moved. */
    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed as for a close, but claims dated inside it can still
     *  be added and changed. Never set together with closed. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The period's due-total fixed when it was closed or soft-closed; none while it is open. */
    @Column(name = "closed_total", precision = 14, scale = 2)
    private BigDecimal closedTotal;

    /** Each person's due-total for the period, by person id, fixed when it was closed or soft-closed; empty while it
     *  is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "due_total", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    /** Each person's carried figure for the period, by person id, fixed when it was closed or soft-closed; empty
     *  while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> closedPersonCarried = new HashMap<>();

    /** Each person's opening balance for the period, by person id: the sum of the amounts pasted for them, added to
     *  their carried figure for it. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "opening", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> personOpenings = new HashMap<>();

    /** The most OPEN or PENDING claims a person may have in the period; none means no cap. */
    @Column(name = "claim_cap")
    private Integer claimCap;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer claimCap) {
        this(sheetId, name, fromDate, toDate);
        this.claimCap = claimCap;
    }

    /** Whether a date falls inside this period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether this period shares a day with the period from {@code from} to {@code to}. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !fromDate.isAfter(to) && !from.isAfter(toDate);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    public Integer getClaimCap() {
        return claimCap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return Map.copyOf(closedPersonTotals);
    }

    public Map<Long, BigDecimal> getClosedPersonCarried() {
        return Map.copyOf(closedPersonCarried);
    }

    public Map<Long, BigDecimal> getPersonOpenings() {
        return Map.copyOf(personOpenings);
    }

    /** A person's opening balance for the period; 0.00 when none was pasted. */
    public BigDecimal openingOf(Long personId) {
        return personOpenings.getOrDefault(personId, BigDecimal.ZERO.setScale(2));
    }

    /** Add an amount to a person's opening balance for the period. */
    public void addOpening(Long personId, BigDecimal amount) {
        personOpenings.merge(personId, amount, BigDecimal::add);
    }

    /** Close the period, fixing each person's due-total and carried figure for it; its own due-total is the sum of
     *  theirs. */
    public void close(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        fix(personTotals, personCarried);
        this.closed = true;
    }

    /** Soft-close the period, fixing each person's due-total for it as a close does, but leaving its claims open to
     *  change. */
    public void softClose(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        fix(personTotals, personCarried);
        this.softClosed = true;
    }

    private void fix(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.closed = false;
        this.softClosed = false;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedPersonCarried.clear();
        this.closedPersonCarried.putAll(personCarried);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total and each person's figures for it are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
        this.closedPersonCarried.clear();
    }
}
package net.officefloor.hq.app.period;

import org.springframework.format.annotation.DateTimeFormat;
import net.officefloor.hq.app.history.SheetHistory;
import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Periods on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/periods")
public class PeriodController {

    /** A period as the screen shows it; softClosed is whether it is soft-closed; closedTotal is its due-total fixed
     *  when it was closed or soft-closed (null while open), and closedPersonTotals each person's, by person id, fixed
     *  then (empty while open; a person missing has 0.00), as closedPersonCarried is each person's carried figure;
     *  personOpenings is each person's opening balance for it, by person id (a person missing has 0.00). */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed, boolean softClosed,
            String closedTotal, Map<Long, String> closedPersonTotals, Integer cap,
            Map<Long, String> closedPersonCarried, Map<Long, String> personOpenings) {

        public static PeriodView of(Period period) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getClosedPersonTotals().forEach((id, total) -> personTotals.put(id, total.toPlainString()));
            Map<Long, String> personCarried = new TreeMap<>();
            period.getClosedPersonCarried().forEach((id, carried) -> personCarried.put(id, carried.toPlainString()));
            Map<Long, String> openings = new TreeMap<>();
            period.getPersonOpenings().forEach((id, opening) -> openings.put(id, opening.toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFromDate(), period.getToDate(),
                    period.isClosed(), period.isSoftClosed(), period.getClosedTotal() == null ? null : period.getClosedTotal().toPlainString(),
                    personTotals, period.getClaimCap(), personCarried, openings);
        }
    }

    /** A period as the form submits it: a name, and its from and to dates, inclusive; a blank
     *  from-date takes the sheet's today. The cap, when given, is the most OPEN or PENDING claims a person may have
     *  in it. */
    public record PeriodForm(@NotBlank @Size(max = 100) String name, LocalDate from, @NotNull LocalDate to,
            @Min(1) @Max(1_000_000) Integer cap) {
    }

    /** A generate request: one period per calendar month from the from-date's month to the to-date's; a blank
     *  from-date takes the sheet's today. */
    public record GenerateForm(LocalDate from, @NotNull LocalDate to) {
    }

    /** A fiscal year generate request: the calendar year the fiscal year starts in. */
    public record GenerateFiscalYearForm(@NotNull @Min(1) @Max(9998) Integer year) {
    }

    /** What a generate made: how many periods, and the periods themselves. */
    public record GenerateView(int made, List<PeriodView> periods) {
    }

    private final PeriodService periods;
    private final SheetHistory history;

    public PeriodController(PeriodService periods, SheetHistory history) {
        this.history = history;
        this.periods = periods;
    }

    @GetMapping
    public List<PeriodView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            return history.viewsAsOf(sheetId, asOf).periods();
        }
        return periods.list(sheetId).stream().map(PeriodView::of).toList();
    }

    @PostMapping
    public PeriodView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodForm request) {
        return PeriodView.of(periods.add(sheetId, user, request.name(), request.from(), request.to(),
                request.cap()));
    }

    @PostMapping("/generate")
    public GenerateView generate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateForm request) {
        List<PeriodView> made = periods.generate(sheetId, user, request.from(), request.to()).stream()
                .map(PeriodView::of).toList();
        return new GenerateView(made.size(), made);
    }

    @PostMapping("/generate-fy")
    public GenerateView generateFiscalYear(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateFiscalYearForm request) {
        List<PeriodView> made = periods.generateFiscalYear(sheetId, user, request.year()).stream()
                .map(PeriodView::of).toList();
        return new GenerateView(made.size(), made);
    }

    @PostMapping("/{name}/close")
    public PeriodView close(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(periods.close(sheetId, user, name));
    }

    @PostMapping("/{name}/soft-close")
    public PeriodView softClose(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(periods.softClose(sheetId, user, name));
    }

    @PostMapping("/{name}/reopen")
    public PeriodView reopen(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return PeriodView.of(periods.reopen(sheetId, user, name));
    }
}
